function cutMiddle(head: ListNode | null): ListNode | null {
  let n = 0;
  for (let p = head; p; p = p.next) n++;
  if (n === 1) return null;
  let prev = head!;
  for (let i = 0; i < Math.floor(n / 2) - 1; i++) prev = prev.next!;
  prev.next = prev.next!.next;
  return head;
}

