class Solution:
    def cutMiddle(self, head: Optional[ListNode]) -> Optional[ListNode]:
        n, p = 0, head
        while p:
            n += 1
            p = p.next
        if n == 1:
            return None
        prev = head
        for _ in range(n // 2 - 1):
            prev = prev.next
        prev.next = prev.next.next
        return head

